package cn.zhuatech.demandai.controller; import cn.zhuatech.demandai.common.ApiResponse; import cn.zhuatech.demandai.dto.DemandAiDto.*; import cn.zhuatech.demandai.service.DemandAiService; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/admin") @PreAuthorize("hasAnyRole('DOMAIN_OPERATOR','QUALITY','ADMIN')") public class OperationsAdminController {private final DemandAiService service;public OperationsAdminController(DemandAiService service){this.service=service;}@GetMapping("/dashboard") public ApiResponse<Dashboard> dashboard(){return ApiResponse.ok(service.adminDashboard());}@GetMapping("/work-orders") public ApiResponse<List<WorkRecordView>> orders(){return ApiResponse.ok(service.workRecords());}}
